const CITIES_DB = [{"id":"mumbai","name":"Mumbai","icon":"","subsidy":"₹10,000","charging":"Good","state":"Maharashtra","guide":["Maharashtra adds up to ₹10,000 on top of the central subsidy and waives road tax and registration for EVs under its 2025 policy, which runs to March 2030.","Our real-world range tests are run on a fixed 10 km loop in Mumbai, so the range figures on this site are the closest match to what you will get here."],"stateId":"maharashtra"},{"id":"delhi","name":"Delhi","icon":"","subsidy":"₹30,000","charging":"Excellent","state":"Delhi NCR","guide":["Delhi has the biggest state subsidy in India: up to ₹30,000 in the first year of the 2026 policy, plus ₹10,000 more if you scrap an old petrol two-wheeler. The amount drops each year, so buying sooner is worth real money."],"stateId":"delhi"},{"id":"bangalore","name":"Bengaluru","icon":"","subsidy":"₹0","charging":"Excellent","state":"Karnataka","guide":["Karnataka pays no cash subsidy, but electric two-wheelers remain fully road tax exempt even after the state moved electric cars to a slab tax in 2026. That keeps on-road prices close to ex-showroom.","Bengaluru is home to both Ather and Ola, so it has the densest network of brand showrooms, service centres and fast chargers in the country. Bounce Infinity's battery swap stations are also most common here, which makes the swappable E1 a realistic option.","Heavy traffic means lower average speeds, which usually helps real-world range. Most riders here get close to the upper end of our measured range figures."],"stateId":"karnataka"},{"id":"hyderabad","name":"Hyderabad","icon":"","subsidy":"₹0","charging":"Good","state":"Telangana","guide":["Telangana gives no cash subsidy on electric scooters, but the 100% road tax and registration waiver makes on-road prices here among the lowest in India. That waiver is due to end on 31 December 2026, so registering before then saves you the road tax.","Telangana registers vehicles on its own system rather than VAHAN, so national sales tables undercount the city. On the road, Ather, Ola, TVS and Bajaj all have showrooms across Hyderabad and Secunderabad, and Hyderabad-based Pure EV has its strongest service presence here.","Hyderabad summers regularly cross 40°C. If your scooter will sit outside in the sun, battery chemistry and a good thermal warranty matter more here than in milder cities. Our LFP vs NMC guide lists which models use which cells."],"featured":["bajaj-chetak-chetak-3501-3point5-kwh","bajaj-chetak-chetak-3503-3point5-kwh","hero-vida-vx2-plus-3point4-kwh","hero-vida-v2-pro-3point94-kwh","hero-vida-vx2-go-2point2-kwh"],"stateId":"telangana"},{"id":"chennai","name":"Chennai","icon":"","subsidy":"₹0","charging":"Good","state":"Tamil Nadu","guide":["Tamil Nadu pays no cash subsidy, but EVs are fully road tax exempt until 31 December 2027. TVS is based in Chennai-adjacent Hosur, and Ather and Ola build their scooters in Tamil Nadu, so service coverage is good."],"stateId":"tamil-nadu"},{"id":"pune","name":"Pune","icon":"","subsidy":"₹10,000","charging":"Good","state":"Maharashtra","guide":["Maharashtra adds up to ₹10,000 on top of the central subsidy and waives road tax for EVs. Pune is Bajaj's home city, so Chetak sales and service are particularly strong here."],"featured":["bajaj-chetak-chetak-3501-3point5-kwh","bajaj-chetak-chetak-3503-3point5-kwh","hero-vida-vx2-plus-3point4-kwh","hero-vida-v2-pro-3point94-kwh","hero-vida-vx2-go-2point2-kwh"],"stateId":"maharashtra"},{"id":"ahmedabad","name":"Ahmedabad","icon":"","subsidy":"₹0","charging":"Moderate","state":"Gujarat","guide":["Gujarat's purchase subsidy ended in 2023 and the 1% concessional road tax ran out on 31 March 2026. We could not confirm the current road tax rule, so our on-road figures here leave road tax out. Ask your dealer or RTO."],"featured":["bajaj-chetak-chetak-3501-3point5-kwh","bajaj-chetak-chetak-3503-3point5-kwh","hero-vida-vx2-plus-3point4-kwh","hero-vida-v2-pro-3point94-kwh","hero-vida-vx2-go-2point2-kwh"],"stateId":"gujarat"},{"id":"kolkata","name":"Kolkata","icon":"","subsidy":"₹0","charging":"Moderate","state":"West Bengal","guide":["West Bengal has no cash subsidy, and its last confirmed EV road tax exemption ran only to March 2025. Our on-road figures here leave road tax out because we could not confirm the current rule."],"stateId":"west-bengal"},{"id":"jaipur","name":"Jaipur","icon":"","subsidy":"₹10,000","charging":"Developing","state":"Rajasthan","guide":["Rajasthan pays ₹5,000 to ₹10,000 depending on battery size, plus SGST reimbursement, though disbursement has been slow. EVs are road tax exempt."],"stateId":"rajasthan"},{"id":"lucknow","name":"Lucknow","icon":"","subsidy":"₹0","charging":"Developing","state":"Uttar Pradesh","guide":["Uttar Pradesh's purchase subsidy closed in October 2023, but road tax and registration are waived for EVs until 13 October 2027."],"stateId":"uttar-pradesh"},{"id":"surat","name":"Surat","icon":"","subsidy":"₹0","charging":"Good","state":"Gujarat","guide":["Gujarat's purchase subsidy ended in 2023 and the 1% concessional road tax ran out on 31 March 2026. We could not confirm the current road tax rule, so our on-road figures here leave road tax out. Ask your dealer or RTO."],"stateId":"gujarat"},{"id":"chandigarh","name":"Chandigarh","icon":"","subsidy":"Unclear","charging":"Good","state":"Punjab/Haryana","guide":["Chandigarh waives road tax on EVs. Cash incentives are uncertain, with reports in early 2026 that they may not be paid for the rest of the policy period."],"stateId":"chandigarh"}];

